"""Nightly raw-drop pipeline. Generated by pipeline-builder from 7 source files.

land_<table>  copy one raw file into the warehouse as text, keeping file row positions
validate_drop run the validation rules and stop if any table quarantines too much
dbt_build     build and test staging, quarantine and mart models
"""

from datetime import datetime, timedelta

from airflow import DAG
from airflow.models.baseoperator import chain
from airflow.operators.bash import BashOperator
from airflow.operators.python import PythonOperator

from pipeline_builder.runtime import land_source, validate_drop

RAW_DIR = "data/raw"
WAREHOUSE = "generated/warehouse.duckdb"
DBT_DIR = "generated/dbt"
RULES = "generated/rules.yml"
CATALOG = "generated/catalog.yml"

with DAG(
    dag_id="raw_drop_pipeline",
    schedule="0 3 * * *",
    start_date=datetime(2026, 1, 1),
    catchup=False,
    max_active_runs=1,
    default_args={"retries": 2, "retry_delay": timedelta(minutes=5)},
    tags=["generated", "raw-drop"],
) as dag:
    land_customers = PythonOperator(
        task_id="land_customers",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/customers.csv", "table": "customers", "warehouse": WAREHOUSE},
    )
    land_order_items = PythonOperator(
        task_id="land_order_items",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/order_items.parquet", "table": "order_items", "warehouse": WAREHOUSE},
    )
    land_orders = PythonOperator(
        task_id="land_orders",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/orders.csv", "table": "orders", "warehouse": WAREHOUSE},
    )
    land_payments = PythonOperator(
        task_id="land_payments",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/payments.csv", "table": "payments", "warehouse": WAREHOUSE},
    )
    land_products = PythonOperator(
        task_id="land_products",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/products.json", "table": "products", "warehouse": WAREHOUSE},
    )
    land_returns = PythonOperator(
        task_id="land_returns",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/returns.jsonl", "table": "returns", "warehouse": WAREHOUSE},
    )
    land_stores = PythonOperator(
        task_id="land_stores",
        python_callable=land_source,
        op_kwargs={"path": f"{RAW_DIR}/stores.csv", "table": "stores", "warehouse": WAREHOUSE},
    )

    validate = PythonOperator(
        task_id="validate_drop",
        python_callable=validate_drop,
        op_kwargs={
            "raw_dir": RAW_DIR,
            "catalog_path": CATALOG,
            "rules_path": RULES,
            "max_quarantine_rate": 0.05,
        },
    )

    dbt_build = BashOperator(
        task_id="dbt_build",
        bash_command=f"dbt build --project-dir {DBT_DIR} --profiles-dir {DBT_DIR}",
        env={"WAREHOUSE_PATH": WAREHOUSE},
        append_env=True,
    )

    # Landing runs one file at a time: DuckDB allows a single writing process per database
    # file, so parallel land tasks would fail on the lock.
    chain(land_customers, land_order_items, land_orders, land_payments, land_products, land_returns, land_stores, validate, dbt_build)
